# ! [feature (try_from)] use std :: convert :: TryInto ; pub enum Value { Float (f32) , List (Vec < Value >) , } impl TryInto < f32 > for Value { type Error = () ; fn try_into (self) -> Result < f32 , () > { match self { Value :: Float (val) => Ok (val) , _ => Err (()) , } } } impl < T > TryInto < Vec < T > > for Value where Value : TryInto < T , Error = () > { type Error = () ; fn try_into (self) -> Result < Vec < T > , () > { match self { Value :: List (list) => { list . into_iter () . map (< Value as TryInto < T > > :: try_into) . collect () } , _ => Err (()) , } } } pub fn example (val : Value) -> Result < Vec < f32 > , () > { val . try_into () }